const input = $json.body ?? {};

function normalizeDate(value) {
  const date = String(value ?? '').trim();

  // Already in our standard format
  if (/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    return date;
  }

  // For this lab, we accept DD/MM/YYYY
  const match = date.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

  if (match) {
    const [, day, month, year] = match;

    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }

  // Don't invent/fix a date we don't understand
  return date;
}

return {
  json: {
    raw_input: input,

    normalized: {
  name: String(input.name ?? '').trim(),

  company: String(input.company ?? '').trim(),

  email: String(input.email ?? '')
    .trim()
    .toLowerCase(),

  phone: String(input.phone ?? '')
    .replace(/\D/g, ''),

  country: String(input.country ?? '')
    .trim()
    .toUpperCase(),

  preferred_contact_date: normalizeDate(
    input.preferred_contact_date
  )
}

  }
};

const data = $json.normalized;
const errors = [];

// Required fields
if (!data.name) {
  errors.push('name is required');
}

if (!data.email) {
  errors.push('email is required');
}

if (!data.phone) {
  errors.push('phone is required');
}

if (!data.preferred_contact_date) {
  errors.push('preferred_contact_date is required');
}

// Email validation
if (
  data.email &&
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)
) {
  errors.push('email is invalid');
}

// Phone validation
if (
  data.phone &&
  !/^\d{10,15}$/.test(data.phone)
) {
  errors.push('phone must contain 10 to 15 digits');
}

// Date validation
if (data.preferred_contact_date) {
  const match = data.preferred_contact_date.match(
    /^(\d{4})-(\d{2})-(\d{2})$/
  );

  let validDate = false;

  if (match) {
    const [, year, month, day] = match;

    const date = new Date(
      Number(year),
      Number(month) - 1,
      Number(day)
    );

    validDate =
      date.getFullYear() === Number(year) &&
      date.getMonth() === Number(month) - 1 &&
      date.getDate() === Number(day);
  }

  if (!validDate) {
    errors.push('preferred_contact_date is invalid');
  }
}

return {
  json: {
    ...$json,

    validation: {
      is_valid: errors.length === 0,
      errors
    }
  }
};

